import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Модерация","description":"","frontmatter":{},"headers":[],"relativePath":"guide/moderation/index.md","filePath":"guide/moderation/index.md","lastUpdated":0}`),a={name:`guide/moderation/index.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="модерация" tabindex="-1">Модерация <a class="header-anchor" href="#модерация" aria-label="Permalink to “Модерация”">​</a></h1><p>Инструменты вкладки <strong>«Модерация»</strong> в попапе настроек: они помогают проверять поток правок и следить за конкретными объектами. Всё работает поверх нативной панели истории редактора и не заменяет её.</p><h2 id="feeds-filter" tabindex="-1">Фильтр истории правок <a class="header-anchor" href="#feeds-filter" aria-label="Permalink to “Фильтр истории правок”">​</a></h2><p><strong>Где:</strong> Настройки → Модерация → «Фильтр истории правок».</p><p>Добавляет в ленту истории правок два выпадающих фильтра и автоподгрузку истории за выбранный период. По умолчанию функция выключена.</p><p>Что появляется:</p><ul><li><strong>Фильтр по статусу</strong> — «Все статусы», «Опубликована», «Одобрена», «На рассмотрении», «Не принята». В списке видны счётчики по каждому статусу.</li><li><strong>Фильтр по действию</strong> — «Все действия», «Удаления», «Редактирование», «Создание».</li><li><strong>Период</strong> — 1, 3 или 7 дней. При выборе периода лента сама прокручивается и подгружает события за это время; загрузку можно остановить.</li></ul><p>Фильтры комбинируются: например, «Удаления» + «Не принята» + 7 дней покажет отклонённые удаления за неделю.</p><p>Сценарии:</p><ul><li><strong>Проверить удаления за неделю.</strong> Модератор выбирает «Удаления» и 7 дней, чтобы пройтись по всем удалениям, не листая ленту вручную.</li><li><strong>Найти зависшие правки.</strong> Статус «На рассмотрении» и период 3 дня — список того, что ждёт решения.</li><li><strong>Проконтролировать свои правки.</strong> Статус «Не принята» — что вернули и почему.</li></ul><div class="tip custom-block"><p class="custom-block-title">Лента не перезагружается</p><p>Фильтр скрывает и показывает уже существующие карточки, а не запрашивает данные заново. Если событие старше загруженного периода, выберите больший период.</p></div><h2 id="object-tracker" tabindex="-1">Наблюдение за объектами <a class="header-anchor" href="#object-tracker" aria-label="Permalink to “Наблюдение за объектами”">​</a></h2><p><strong>Где:</strong> Настройки → Модерация → «Наблюдение за объектами».</p><p>Добавляет в панель истории вкладку <strong>«Мои объекты»</strong>: в ней собрана история правок выбранных объектов — в том же формате, что нативная лента «Мои правки».</p><p>Как добавить объект:</p><ul><li><strong>Через меню объекта.</strong> Откройте карточку объекта, меню «Ещё» → «Наблюдать». У наблюдаемого объекта пункт называется «Не наблюдать».</li><li><strong>По идентификатору.</strong> Во вкладке «Мои объекты» введите id объекта вручную.</li></ul><p>Ограничения и поведение:</p><ul><li>не больше 30 наблюдаемых объектов;</li><li>повторное добавление того же объекта даёт сообщение «Объект уже добавлен в «Мои объекты»»;</li><li>если редактор ограничил частоту запросов, расширение ставит опрос на паузу и повторяет его позже; кнопка обновления в карточке запускает проверку вручную;</li><li>снять объект с наблюдения можно из меню «Ещё» или из вкладки «Мои объекты».</li></ul><p>Сценарии:</p><ul><li><strong>Спорный объект.</strong> Наблюдайте за объектом, который правят несколько человек, и смотрите, кто и когда менял геометрию.</li><li><strong>Своя зона ответственности.</strong> Добавьте 10–15 объектов района и проверяйте ленту правок по ним, не просматривая всю историю карты.</li><li><strong>Проверка после замечания.</strong> Добавьте объект из замечания, чтобы увидеть, исправление пришло и кем.</li></ul><div class="info custom-block"><p class="custom-block-title">Терминология</p><p>В интерфейсе используется слово «наблюдение», а не «отслеживание»: так пункт меню совпадает с нативной терминологией редактора.</p></div>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};